<?php
declare(strict_types=1);$root=dirname(__DIR__);require_once $root.'/app/Support/Realtime.php';
function envc($p){$v=@parse_ini_file($p,false,INI_SCANNER_RAW);return is_array($v)?$v:[];}function db(){static $p;if($p)return $p;global $root;$e=envc($root.'/.env');return $p=new PDO('mysql:host='.($e['DB_HOST']??'127.0.0.1').';port='.($e['DB_PORT']??3306).';dbname='.($e['DB_DATABASE']??'zynko').';charset=utf8mb4',$e['DB_USERNAME']??'root',$e['DB_PASSWORD']??'',[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);}function out($ok,$msg,$data=[],$code=200){http_response_code($code);header('Content-Type: application/json; charset=utf-8');echo json_encode(['ok'=>$ok,'message'=>$msg,'data'=>$data],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;}function uuid4(){ $d=random_bytes(16);$d[6]=chr((ord($d[6])&15)|64);$d[8]=chr((ord($d[8])&63)|128);return vsprintf('%s%s-%s-%s-%s-%s%s%s',str_split(bin2hex($d),4));}function b64u($s){return rtrim(strtr(base64_encode($s),'+/','-_'),'=');}
$origin=$_SERVER['HTTP_ORIGIN']??'';$originHost=strtolower((string)parse_url($origin,PHP_URL_HOST));if($origin){header('Access-Control-Allow-Origin: '.$origin);header('Vary: Origin');}header('Access-Control-Allow-Methods: GET, POST, OPTIONS');header('Access-Control-Allow-Headers: Content-Type');if($_SERVER['REQUEST_METHOD']==='OPTIONS')exit;
try{$pdo=db();$input=json_decode(file_get_contents('php://input'),true)?:$_POST;$action=$input['action']??($_GET['action']??'bootstrap');$key=preg_replace('/[^a-f0-9]/','',strtolower((string)($input['key']??$_GET['key']??'')));$q=$pdo->prepare('SELECT w.*,t.name company,t.logo_path FROM webchat_widgets w JOIN tenants t ON t.id=w.tenant_id WHERE w.public_key=? AND w.enabled=1 LIMIT 1');$q->execute([$key]);$w=$q->fetch();if(!$w)out(false,'Widget no disponible.',[],404);$tid=(int)$w['tenant_id'];$wid=(int)$w['id'];
$q=$pdo->prepare('SELECT * FROM webchat_installations WHERE widget_id=? AND enabled=1 AND domain IN (?,?) LIMIT 1');$q->execute([$wid,$originHost,$_SERVER['HTTP_HOST']??'']);$installation=$q->fetch();if(!$installation)out(false,'Este dominio no está autorizado para usar NIVO Web Chat.',[],403);$pdo->prepare('UPDATE webchat_installations SET first_seen_at=COALESCE(first_seen_at,NOW()),last_seen_at=NOW() WHERE id=?')->execute([$installation['id']]);
$visitor=(string)($input['visitor_token']??$_GET['visitor_token']??'');$v=null;if($visitor!==''){$q=$pdo->prepare('SELECT * FROM webchat_visitors WHERE visitor_token=? AND tenant_id=? AND widget_id=?');$q->execute([$visitor,$tid,$wid]);$v=$q->fetch();}
if($action==='bootstrap'){if(!$v){$visitor=bin2hex(random_bytes(32));$pdo->prepare('INSERT INTO webchat_visitors(tenant_id,widget_id,visitor_token,origin_domain) VALUES(?,?,?,?)')->execute([$tid,$wid,$visitor,$originHost]);$v=['id'=>(int)$pdo->lastInsertId(),'visitor_token'=>$visitor,'conversation_id'=>null];}else{$pdo->prepare('UPDATE webchat_visitors SET last_seen_at=NOW(),origin_domain=? WHERE id=?')->execute([$originHost,$v['id']]);}$messages=[];$cid=(int)($v['conversation_id']??0);if($cid){$q=$pdo->prepare('SELECT id,direction,sender_type,body,sent_at FROM messages WHERE tenant_id=? AND conversation_id=? ORDER BY id');$q->execute([$tid,$cid]);$messages=$q->fetchAll();}$e=envc($root.'/.env');$host=$e['WS_PUBLIC_HOST']??($_SERVER['HTTP_HOST']??'localhost');$host=preg_replace('/:\d+$/','',$host);$scheme=(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off')?'wss':'ws';$payload=['tenant_id'=>$tid,'visitor_id'=>(int)$v['id'],'conversation_id'=>$cid,'exp'=>time()+43200,'aud'=>'webchat'];$b=b64u(json_encode($payload));$sig=preg_match('/^[a-f0-9]{64}$/i',$e['APP_KEY']??'')?hash_hmac('sha256',$b,hex2bin($e['APP_KEY']),true):'';$ws=$scheme.'://'.$host.':'.((int)($e['WS_PORT']??8080));out(true,'NIVO Web Chat listo.',['visitor_token'=>$visitor,'conversation_id'=>$cid,'widget'=>['company'=>$w['company'],'name'=>$w['name'],'position'=>$w['position'],'offset_x'=>(int)$w['offset_x'],'offset_y'=>(int)$w['offset_y'],'accent_color'=>$w['accent_color'],'welcome_title'=>$w['welcome_title'],'welcome_message'=>$w['welcome_message'],'ask_name'=>(bool)$w['ask_name'],'ask_email'=>(bool)$w['ask_email']],'messages'=>$messages,'ws_url'=>$ws,'ws_token'=>$b.'.'.b64u($sig)]);}
if(!$v)out(false,'Sesión del visitante inválida.',[],401);
if($action==='send'){$body=trim((string)($input['body']??''));if($body==='')out(false,'Escribe un mensaje.',[],422);$cid=(int)($v['conversation_id']??0);if(!$cid){$name=trim((string)($input['name']??''));$email=trim((string)($input['email']??''));if($name==='')$name='Visitante web';$pdo->beginTransaction();$pdo->prepare('INSERT INTO contacts(tenant_id,uuid,name,email) VALUES(?,?,?,?)')->execute([$tid,uuid4(),$name,$email?:null]);$contact=(int)$pdo->lastInsertId();$pdo->prepare("INSERT INTO conversations(tenant_id,uuid,channel_id,contact_id,status,last_message_at) VALUES(?,?,?,?, 'open',NOW())")->execute([$tid,uuid4(),(int)$w['channel_id'],$contact]);$cid=(int)$pdo->lastInsertId();$pdo->prepare('UPDATE webchat_visitors SET contact_id=?,conversation_id=?,name=?,email=?,last_seen_at=NOW() WHERE id=?')->execute([$contact,$cid,$name,$email?:null,$v['id']]);$pdo->commit();zynkoRealtimePublish($pdo,$tid,'conversation.created',['conversation_id'=>$cid,'channel'=>'webchat','contact_name'=>$name],'conversation',(string)$cid);} $pdo->prepare("INSERT INTO messages(tenant_id,conversation_id,uuid,direction,sender_type,type,body,status,sent_at) VALUES(?,?,?,'in','contact','text',?,'received',NOW())")->execute([$tid,$cid,uuid4(),$body]);$pdo->prepare('UPDATE conversations SET unread_count=unread_count+1,last_message_at=NOW() WHERE id=? AND tenant_id=?')->execute([$cid,$tid]);zynkoRealtimePublish($pdo,$tid,'message.created',['conversation_id'=>$cid,'channel'=>'webchat'],'conversation',(string)$cid);
// NIVO: rules -> approved knowledge -> safe handoff
$bp=$pdo->prepare('SELECT enabled,fallback_message,handoff_rules_json FROM bot_profiles WHERE tenant_id=?');$bp->execute([$tid]);$bot=$bp->fetch();$reply=null;$handoff=false;if($bot&&(int)$bot['enabled']===1){$norm=mb_strtolower($body);if(preg_match('/\b(agente|asesor|persona|humano|representante)\b/u',$norm)){$handoff=true;$reply='Claro. Voy a transferirte con un agente de '.$w['company'].'.';}else{$rq=$pdo->prepare('SELECT name,keywords,response FROM nivo_rules WHERE tenant_id=? AND active=1 ORDER BY priority,id');$rq->execute([$tid]);foreach($rq->fetchAll() as $r){foreach(array_filter(array_map('trim',explode(',',mb_strtolower($r['keywords'])))) as $kw)if($kw!==''&&mb_strpos($norm,$kw)!==false){$reply=$r['response'];break 2;}}if($reply===null){$words=array_values(array_unique(array_filter(preg_split('/[^\p{L}\p{N}]+/u',$norm),fn($x)=>mb_strlen($x)>=3)));$q=$pdo->prepare("SELECT name,content FROM knowledge_sources WHERE tenant_id=? AND status='ready' AND content IS NOT NULL ORDER BY updated_at DESC LIMIT 200");$q->execute([$tid]);$best=null;$score=0;foreach($q->fetchAll() as $r){$hay=mb_strtolower(($r['name']??'').' '.($r['content']??''));$n=0;foreach($words as $word)if(mb_strpos($hay,$word)!==false)$n++;if($n>$score){$score=$n;$best=$r;}}if($best&&$score>=2)$reply=mb_strlen(trim($best['content']))>900?mb_substr(trim($best['content']),0,900).'…':trim($best['content']);else{$reply=$bot['fallback_message']?:'No tengo información suficiente para responder con seguridad. Te comunicaré con un agente.';$handoff=true;}}}if($reply){$pdo->prepare("INSERT INTO messages(tenant_id,conversation_id,uuid,direction,sender_type,type,body,status,sent_at) VALUES(?,?,?,'out','bot','text',?,'sent',NOW())")->execute([$tid,$cid,uuid4(),$reply]);if($handoff)$pdo->prepare("UPDATE conversations SET status='pending' WHERE id=? AND tenant_id=?")->execute([$cid,$tid]);zynkoRealtimePublish($pdo,$tid,'message.created',['conversation_id'=>$cid,'channel'=>'webchat','sender'=>'bot'],'conversation',(string)$cid);}}
out(true,'Mensaje recibido.',['conversation_id'=>$cid]);}
if($action==='messages'){$cid=(int)($v['conversation_id']??0);$messages=[];if($cid){$q=$pdo->prepare('SELECT id,direction,sender_type,body,sent_at FROM messages WHERE tenant_id=? AND conversation_id=? ORDER BY id');$q->execute([$tid,$cid]);$messages=$q->fetchAll();}out(true,'OK',['conversation_id'=>$cid,'messages'=>$messages]);}out(false,'Acción no válida.',[],400);
}catch(Throwable $e){out(false,'No fue posible procesar el chat: '.$e->getMessage(),[],500);}
